from __future__ import annotations

MAX_DIM = 100
MIN_QUALITY = 30
GOOD_QUALITY = 60
SATURATION_LIMIT = 5

CellKey = tuple[int, int]
Flags = list[list[str]]
Cells = list[list[int]]


def accumulate_grid(raw: object) -> dict:
    """Aggregate observations into a per-cell grid of averaged values.

    Validates the input, snaps each observation to a cell, and returns the
    averaged cells, per-cell flags, and summary statistics. Cells with no
    observations are filled with ``fill_value``.
    """
    if not isinstance(raw, dict):
        return {"ok": False, "error": "malformed input"}
    if "grid" not in raw or "observations" not in raw or "fill_value" not in raw:
        return {"ok": False, "error": "missing field"}

    ok, grid = _validate_grid(raw["grid"])
    if not ok:
        return {"ok": False, "error": grid}
    if not isinstance(raw["fill_value"], int):
        return {"ok": False, "error": "bad fill value"}
    observations = raw["observations"]
    if not isinstance(observations, list):
        return {"ok": False, "error": "bad observations"}

    width = grid["width"]
    height = grid["height"]
    cell_size = grid["cell_size"]
    tolerance = cell_size // 2

    sums: dict[CellKey, int] = {}
    counts: dict[CellKey, int] = {}
    degraded: set[CellKey] = set()
    dropped = rejected = saturated = 0

    for obs in observations:
        error = _validate_observation(obs)
        if error is not None:
            return {"ok": False, "error": error}

        if obs["quality"] < MIN_QUALITY:
            rejected += 1
            continue

        cell = _locate_cell(obs, width, height, cell_size, tolerance)
        if cell is None:
            dropped += 1
            continue
        row, col = cell
        key = (row, col)

        if counts.get(key, 0) >= SATURATION_LIMIT:
            saturated += 1
            continue
        sums[key] = sums.get(key, 0) + obs["value"]
        counts[key] = counts.get(key, 0) + 1
        if obs["quality"] < GOOD_QUALITY:
            degraded.add(key)

    cells = _averaged_rows(sums, counts, width, height, raw["fill_value"])
    flags = _flag_rows(counts, degraded, width, height)
    coverage = _coverage(counts, width, height)
    line = _summary_line(width * height, len(counts), dropped, rejected, saturated, coverage)
    return {
        "ok": True,
        "cells": cells,
        "flags": flags,
        "dropped": dropped,
        "rejected": rejected,
        "saturated": saturated,
        "coverage": coverage,
        "line": line,
    }


def _validate_grid(grid: object) -> tuple[bool, dict | str]:
    """Validate the grid payload, returning it as a dict on success."""
    if not isinstance(grid, dict):
        return False, "bad grid"
    if "width" not in grid or "height" not in grid or "cell_size" not in grid:
        return False, "bad grid"
    width = grid["width"]
    height = grid["height"]
    cell_size = grid["cell_size"]
    if not isinstance(width, int) or width < 1 or width > MAX_DIM:
        return False, "bad width"
    if not isinstance(height, int) or height < 1 or height > MAX_DIM:
        return False, "bad height"
    if not isinstance(cell_size, int) or cell_size < 1:
        return False, "bad cell size"
    return True, grid


def _validate_observation(obs: object) -> str | None:
    """Validate a single observation; return an error message or None."""
    if not isinstance(obs, dict):
        return "bad observation"
    for field in ("x", "y", "value", "quality"):
        if field not in obs or not isinstance(obs[field], int):
            return "bad observation"
    if obs["quality"] < 0 or obs["quality"] > 100:
        return "bad observation"
    return None


def _locate_cell(
    obs: dict, width: int, height: int, cell_size: int, tolerance: int
) -> CellKey | None:
    """Snap an observation to a grid cell, or None if it falls outside."""
    x = obs["x"]
    if x < 0:
        return None
    col = x // cell_size
    if col >= width:
        if x - width * cell_size < tolerance:
            col = width - 1
        else:
            return None

    y = obs["y"]
    if y < 0:
        return None
    row = y // cell_size
    if row >= height:
        if y - height * cell_size < tolerance:
            row = height - 1
        else:
            return None

    return row, col


def _averaged_rows(sums: dict, counts: dict, width: int, height: int, fill_value: int) -> Cells:
    rows = []
    for row in range(height):
        cells = []
        for col in range(width):
            key = (row, col)
            cells.append(sums[key] // counts[key] if key in counts else fill_value)
        rows.append(cells)
    return rows


def _flag_rows(counts: dict, degraded: set[CellKey], width: int, height: int) -> Flags:
    rows = []
    for row in range(height):
        flags = []
        for col in range(width):
            key = (row, col)
            if key not in counts:
                flags.append("empty")
            elif key in degraded:
                flags.append("degraded")
            else:
                flags.append("good")
        rows.append(flags)
    return rows


def _coverage(counts: dict, width: int, height: int) -> int:
    return len(counts) * 100 // (width * height)


def _summary_line(
    total_cells: int,
    filled: int,
    dropped: int,
    rejected: int,
    saturated: int,
    coverage: int,
) -> str:
    return (
        "cells=" + str(total_cells)
        + ";filled=" + str(filled)
        + ";dropped=" + str(dropped)
        + ";rejected=" + str(rejected)
        + ";saturated=" + str(saturated)
        + ";coverage=" + str(coverage)
    )

