from __future__ import annotations

GRACE_DAYS = 30
LATE_FEE = 15
REINSTATE_SURCHARGE = 25
MAX_STRIKES = 3
TIER_FEES = {"basic": 40, "gold": 90}

_ALLOWED_METHODS = ("card", "transfer")


def _fail(error: str) -> dict:
    return {"ok": False, "error": error}


def _check_tier(member: dict) -> str | None:
    return None if member["tier"] in TIER_FEES else "unknown tier"


def _check_amount(payment: dict) -> str | None:
    amount = payment["amount"]
    if not isinstance(amount, int) or amount <= 0:
        return "bad amount"
    return None


def _check_method(payment: dict) -> str | None:
    return None if payment["method"] in _ALLOWED_METHODS else "unsupported method"


def _settle(member: dict, payment: dict, new_status: str, fee: int) -> dict:
    """Common tail: verify the payment covers the fee and build the result."""
    if payment["amount"] < fee:
        return _fail("insufficient payment")
    receipt = f"{payment['method']}:{member['id']}:{new_status}:{fee}"
    return {"ok": True, "status": new_status, "fee": fee, "receipt": receipt}


def _handle_active(member: dict, payment: dict) -> dict:
    if (err := _check_tier(member)):
        return _fail(err)
    if (err := _check_amount(payment)):
        return _fail(err)
    if (err := _check_method(payment)):
        return _fail(err)
    return _settle(member, payment, "renewed", TIER_FEES[member["tier"]])


def _handle_lapsed(member: dict, payment: dict) -> dict:
    if (err := _check_tier(member)):
        return _fail(err)
    if "expired_days" not in member or not isinstance(member["expired_days"], int) or member["expired_days"] < 0:
        return _fail("bad expiry")
    if (err := _check_amount(payment)):
        return _fail(err)
    if (err := _check_method(payment)):
        return _fail(err)
    base = TIER_FEES[member["tier"]]
    if member["expired_days"] <= GRACE_DAYS:
        new_status, fee = "renewed", base + LATE_FEE
    else:
        new_status, fee = "reinstated", base + REINSTATE_SURCHARGE
    return _settle(member, payment, new_status, fee)


def _handle_suspended(member: dict, payment: dict) -> dict:
    if (err := _check_tier(member)):
        return _fail(err)
    if "strikes" not in member or not isinstance(member["strikes"], int) or member["strikes"] < 0:
        return _fail("bad strikes")
    if member["strikes"] >= MAX_STRIKES:
        return _fail("too many strikes")
    if (err := _check_amount(payment)):
        return _fail(err)
    if (err := _check_method(payment)):
        return _fail(err)
    fee = TIER_FEES[member["tier"]] + TIER_FEES[member["tier"]] // 2
    return _settle(member, payment, "reactivated", fee)


_HANDLERS = {
    "active": _handle_active,
    "lapsed": _handle_lapsed,
    "suspended": _handle_suspended,
}


def process_renewal(raw_member: object, raw_payment: object) -> dict:
    if not isinstance(raw_member, dict) or not isinstance(raw_payment, dict):
        return _fail("malformed input")
    member = raw_member
    payment = raw_payment
    if "id" not in member or "status" not in member or "tier" not in member:
        return _fail("missing member field")
    if "amount" not in payment or "method" not in payment:
        return _fail("missing payment field")
    if not isinstance(member["id"], str) or len(member["id"]) == 0:
        return _fail("bad member id")

    status = member["status"]
    if status == "banned":
        return _fail("member banned")

    handler = _HANDLERS.get(status)
    return handler(member, payment) if handler else _fail("unknown status")

from __future__ import annotations

GRACE_DAYS = 30
LATE_FEE = 15
REINSTATE_SURCHARGE = 25
MAX_STRIKES = 3
TIER_FEES = {"basic": 40, "gold": 90}
_TIERS = frozenset(TIER_FEES)
_METHODS = frozenset(("card", "transfer"))


def _validate_input(raw_member: object, raw_payment: object) -> str | None:
    if not isinstance(raw_member, dict) or not isinstance(raw_payment, dict):
        return "malformed input"
    if "id" not in raw_member or "status" not in raw_member or "tier" not in raw_member:
        return "missing member field"
    if "amount" not in raw_payment or "method" not in raw_payment:
        return "missing payment field"
    if not isinstance(raw_member["id"], str) or len(raw_member["id"]) == 0:
        return "bad member id"
    return None


def _validate_tier(member: dict) -> str | None:
    if member["tier"] not in _TIERS:
        return "unknown tier"
    return None


def _validate_payment(payment: dict) -> str | None:
    if not isinstance(payment["amount"], int) or payment["amount"] <= 0:
        return "bad amount"
    if payment["method"] not in _METHODS:
        return "unsupported method"
    return None


def _receipt(method: str, member_id: str, outcome: str, fee: int) -> str:
    return f"{method}:{member_id}:{outcome}:{fee}"


def process_renewal(raw_member: object, raw_payment: object) -> dict:
    error = _validate_input(raw_member, raw_payment)
    if error is not None:
        return {"ok": False, "error": error}

    member = raw_member
    status = member["status"]

    if status == "banned":
        return {"ok": False, "error": "member banned"}
    if status not in ("active", "lapsed", "suspended"):
        return {"ok": False, "error": "unknown status"}

    error = _validate_tier(member)
    if error is not None:
        return {"ok": False, "error": error}

    if status == "lapsed":
        expired_days = member.get("expired_days")
        if not isinstance(expired_days, int) or expired_days < 0:
            return {"ok": False, "error": "bad expiry"}
    elif status == "suspended":
        strikes = member.get("strikes")
        if not isinstance(strikes, int) or strikes < 0:
            return {"ok": False, "error": "bad strikes"}
        if strikes >= MAX_STRIKES:
            return {"ok": False, "error": "too many strikes"}

    error = _validate_payment(payment := raw_payment)
    if error is not None:
        return {"ok": False, "error": error}

    fee = TIER_FEES[member["tier"]]
    if status == "active":
        new_status = "renewed"
    elif status == "lapsed":
        if expired_days <= GRACE_DAYS:
            new_status = "renewed"
            fee += LATE_FEE
        else:
            new_status = "reinstated"
            fee += REINSTATE_SURCHARGE
    elif status == "suspended":
        new_status = "reactivated"
        fee += fee // 2

    if payment["amount"] < fee:
        return {"ok": False, "error": "insufficient payment"}

    return {
        "ok": True,
        "status": new_status,
        "fee": fee,
        "receipt": _receipt(payment["method"], member["id"], new_status, fee),
    }

from __future__ import annotations

GRACE_DAYS = 30
LATE_FEE = 15
REINSTATE_SURCHARGE = 25
MAX_STRIKES = 3
TIER_FEES = {"basic": 40, "gold": 90}
_VALID_TIERS = frozenset(TIER_FEES)
_VALID_METHODS = ("card", "transfer")


def _valid_days(member: dict) -> bool:
    if "expired_days" not in member:
        return False
    days = member["expired_days"]
    return isinstance(days, int) and days >= 0


def _valid_strikes(member: dict) -> bool:
    if "strikes" not in member:
        return False
    strikes = member["strikes"]
    return isinstance(strikes, int) and strikes >= 0


def _renew_active(member: dict, payment: dict) -> dict:
    if member["tier"] not in _VALID_TIERS:
        return {"ok": False, "error": "unknown tier"}
    if not isinstance(payment["amount"], int) or payment["amount"] <= 0:
        return {"ok": False, "error": "bad amount"}
    if payment["method"] not in _VALID_METHODS:
        return {"ok": False, "error": "unsupported method"}
    fee = TIER_FEES[member["tier"]]
    if payment["amount"] < fee:
        return {"ok": False, "error": "insufficient payment"}
    return {
        "ok": True,
        "status": "renewed",
        "fee": fee,
        "receipt": f"{payment['method']}:{member['id']}:renewed:{fee}",
    }


def _renew_lapsed(member: dict, payment: dict) -> dict:
    if member["tier"] not in _VALID_TIERS:
        return {"ok": False, "error": "unknown tier"}
    if not _valid_days(member):
        return {"ok": False, "error": "bad expiry"}
    if not isinstance(payment["amount"], int) or payment["amount"] <= 0:
        return {"ok": False, "error": "bad amount"}
    if payment["method"] not in _VALID_METHODS:
        return {"ok": False, "error": "unsupported method"}
    if member["expired_days"] <= GRACE_DAYS:
        fee = TIER_FEES[member["tier"]] + LATE_FEE
        new_status = "renewed"
    else:
        fee = TIER_FEES[member["tier"]] + REINSTATE_SURCHARGE
        new_status = "reinstated"
    if payment["amount"] < fee:
        return {"ok": False, "error": "insufficient payment"}
    return {
        "ok": True,
        "status": new_status,
        "fee": fee,
        "receipt": f"{payment['method']}:{member['id']}:{new_status}:{fee}",
    }


def _renew_suspended(member: dict, payment: dict) -> dict:
    if member["tier"] not in _VALID_TIERS:
        return {"ok": False, "error": "unknown tier"}
    if not _valid_strikes(member):
        return {"ok": False, "error": "bad strikes"}
    if member["strikes"] >= MAX_STRIKES:
        return {"ok": False, "error": "too many strikes"}
    if not isinstance(payment["amount"], int) or payment["amount"] <= 0:
        return {"ok": False, "error": "bad amount"}
    if payment["method"] not in _VALID_METHODS:
        return {"ok": False, "error": "unsupported method"}
    tier_fee = TIER_FEES[member["tier"]]
    fee = tier_fee + tier_fee // 2
    if payment["amount"] < fee:
        return {"ok": False, "error": "insufficient payment"}
    return {
        "ok": True,
        "status": "reactivated",
        "fee": fee,
        "receipt": f"{payment['method']}:{member['id']}:reactivated:{fee}",
    }


def _validate_input(raw_member: object, raw_payment: object) -> tuple[dict, dict] | str:
    if not (isinstance(raw_member, dict) and isinstance(raw_payment, dict)):
        return "malformed input"
    member, payment = raw_member, raw_payment
    if not {"id", "status", "tier"}.issubset(member):
        return "missing member field"
    if not {"amount", "method"}.issubset(payment):
        return "missing payment field"
    if not isinstance(member["id"], str) or len(member["id"]) == 0:
        return "bad member id"
    return member, payment


def process_renewal(raw_member: object, raw_payment: object) -> dict:
    validated = _validate_input(raw_member, raw_payment)
    if isinstance(validated, str):
        return {"ok": False, "error": validated}
    member, payment = validated

    if member["status"] == "banned":
        return {"ok": False, "error": "member banned"}

    handlers = {
        "active": _renew_active,
        "lapsed": _renew_lapsed,
        "suspended": _renew_suspended,
    }
    handler = handlers.get(member["status"])
    if handler is None:
        return {"ok": False, "error": "unknown status"}
    return handler(member, payment)

