export interface QuoteResult {
  ok: boolean;
  error?: string;
  total?: number;
  policy?: string;
  line?: string;
}

interface CategoryConfig {
  name: string;
  minNights: number;
  maxNights: number;
  minGuests: number;
  maxGuests: number;
  baseRate: number;        // charge per night in low season
  highRate: number;        // extra per night in high season
  cleaningFee?: number;    // flat add-on
  extraGuestFrom?: number; // guests strictly above this pay extraGuestFee
  extraGuestFee?: number;  // flat add-on per qualifying booking
  minimumStay?: number;    // enforced min nights (checked after the 1..maxNights range)
  minimumStayError?: string;
}

const CATEGORIES: Record<string, CategoryConfig> = {
  standard: {
    name: "standard",
    minNights: 1,
    maxNights: 14,
    minGuests: 1,
    maxGuests: 2,
    baseRate: 80,
    highRate: 30,
  },
  suite: {
    name: "suite",
    minNights: 1,
    maxNights: 21,
    minGuests: 1,
    maxGuests: 4,
    baseRate: 150,
    highRate: 60,
    extraGuestFrom: 2,
    extraGuestFee: 25,
  },
  villa: {
    name: "villa",
    minNights: 1,
    maxNights: 28,
    minGuests: 1,
    maxGuests: 8,
    baseRate: 300,
    highRate: 120,
    cleaningFee: 500,
    minimumStay: 3,
    minimumStayError: "villa minimum stay",
  },
};

// True when the value is an integer within [min, max] inclusive.
function integerInRange(value: unknown, min: number, max: number): boolean {
  return Number.isInteger(value) && (value as number) >= min && (value as number) <= max;
}

export function quoteBooking(raw: unknown): QuoteResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed request" };
  }

  const req = raw as Record<string, unknown>;
  const loyaltyYears = req.loyaltyYears as number;
  if (!Number.isInteger(loyaltyYears) || loyaltyYears < 0) {
    return { ok: false, error: "bad loyalty" };
  }

  const config = CATEGORIES[req.category as string];
  if (!config) {
    return { ok: false, error: "unknown category" };
  }

  const nights = req.nights as number;
  if (!integerInRange(req.nights, config.minNights, config.maxNights)) {
    return { ok: false, error: "bad nights" };
  }
  if (config.minimumStay !== undefined && nights < config.minimumStay) {
    return { ok: false, error: config.minimumStayError };
  }

  const guests = req.guests as number;
  if (!integerInRange(req.guests, config.minGuests, config.maxGuests)) {
    return { ok: false, error: "bad guests" };
  }

  const season = req.season;
  if (season !== "low" && season !== "high") {
    return { ok: false, error: "bad season" };
  }

  // VIP coupon or >=3 years of loyalty earns the discount and the flexible
  // cancellation policy in every category. (loyaltyYears is validated as an
  // integer, so "> 2" and ">= 3" are equivalent to the original conditions.)
  const privileged = req.coupon === "VIP" || loyaltyYears >= 3;

  let total = (config.baseRate + (season === "high" ? config.highRate : 0)) * nights;
  if (privileged) {
    total -= Math.floor(total / 10);
  }
  if (config.extraGuestFee !== undefined && guests > (config.extraGuestFrom as number)) {
    total += config.extraGuestFee;
  }
  if (config.cleaningFee !== undefined) {
    total += config.cleaningFee;
  }

  const policy = privileged ? "flex" : "strict";
  const line = `${config.name}:${nights}n:${total}:${policy}`;
  return { ok: true, total, policy, line };
}

export interface QuoteResult {
  ok: boolean;
  error?: string;
  total?: number;
  policy?: string;
  line?: string;
}

/** A loyalty predicate: either `years >= threshold` or `years > threshold`. */
interface LoyaltyRule {
  threshold: number;
  /** true => strict `>` comparison, false => `>=` */
  strict: boolean;
}

interface CategoryRule {
  name: string;
  minNights: number;
  maxNights: number;
  /** Optional extra minimum stay (e.g. villa requires 3 nights). */
  minStay?: number;
  minGuests: number;
  maxGuests: number;
  /** Base rate per night. */
  nightsRate: number;
  /** Extra per night charged in the high season. */
  highSurcharge: number;
  discount: LoyaltyRule;
  policy: LoyaltyRule;
  /** One-time fee applied to bookings with more than 2 guests. */
  guestFee: number;
  /** One-time fee applied after the discount. */
  fixedFee: number;
}

const CATEGORIES: Record<string, CategoryRule> = {
  standard: {
    name: "standard",
    minNights: 1,
    maxNights: 14,
    minGuests: 1,
    maxGuests: 2,
    nightsRate: 80,
    highSurcharge: 30,
    discount: { threshold: 3, strict: false },
    policy: { threshold: 2, strict: true },
    guestFee: 0,
    fixedFee: 0,
  },
  suite: {
    name: "suite",
    minNights: 1,
    maxNights: 21,
    minGuests: 1,
    maxGuests: 4,
    nightsRate: 150,
    highSurcharge: 60,
    discount: { threshold: 3, strict: false },
    policy: { threshold: 3, strict: false },
    guestFee: 25,
    fixedFee: 0,
  },
  villa: {
    name: "villa",
    minNights: 1,
    maxNights: 28,
    minStay: 3,
    minGuests: 1,
    maxGuests: 8,
    nightsRate: 300,
    highSurcharge: 120,
    discount: { threshold: 2, strict: true },
    policy: { threshold: 3, strict: false },
    guestFee: 0,
    fixedFee: 500,
  },
};

function applies(rule: LoyaltyRule, loyaltyYears: number, vipCoupon: boolean): boolean {
  const loyalEnough = rule.strict
    ? loyaltyYears > rule.threshold
    : loyaltyYears >= rule.threshold;
  return vipCoupon || loyalEnough;
}

export function quoteBooking(raw: unknown): QuoteResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed request" };
  }
  const req = raw as Record<string, unknown>;

  if (!Number.isInteger(req.loyaltyYears) || (req.loyaltyYears as number) < 0) {
    return { ok: false, error: "bad loyalty" };
  }

  const rule = CATEGORIES[req.category as string];
  if (!rule) {
    return { ok: false, error: "unknown category" };
  }

  const loyaltyYears = req.loyaltyYears as number;
  const nights = req.nights as number;
  const guests = req.guests as number;
  const season = req.season;
  const vipCoupon = req.coupon === "VIP";

  // Validation order mirrors the original per-category ordering.
  if (!Number.isInteger(nights) || nights < rule.minNights || nights > rule.maxNights) {
    return { ok: false, error: "bad nights" };
  }
  if (rule.minStay !== undefined && nights < rule.minStay) {
    return { ok: false, error: "villa minimum stay" };
  }
  if (!Number.isInteger(guests) || guests < rule.minGuests || guests > rule.maxGuests) {
    return { ok: false, error: "bad guests" };
  }
  if (season !== "low" && season !== "high") {
    return { ok: false, error: "bad season" };
  }

  let total = rule.nightsRate * nights;
  if (season === "high") {
    total += rule.highSurcharge * nights;
  }
  if (applies(rule.discount, loyaltyYears, vipCoupon)) {
    total -= Math.floor(total / 10);
  }
  if (guests > 2) {
    total += rule.guestFee;
  }
  total += rule.fixedFee;

  const policy = applies(rule.policy, loyaltyYears, vipCoupon) ? "flex" : "strict";
  const line = `${rule.name}:${nights}n:${total}:${policy}`;
  return { ok: true, total, policy, line };
}

